    /*
     * Add to the ConversionEvents
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	TrackingPixel
     */
    public TrackingPixel addToConversionEvents( UUID parentId, ConversionEvent addTo ) {
	    LOGGER.info("handling AssignConversionEventsToTrackingPixelEvent - " );
	    
	    TrackingPixel parentEntity = repository.findById(parentId).get();
	    ConversionEvent child = registry.project( ConversionEvent.class, addTo.getConversionEventId());
	    
	    parentEntity.getConversionEvents().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the ConversionEvents
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	TrackingPixel
     */
	public TrackingPixel removeFromConversionEvents( UUID parentId, ConversionEvent removeFrom ) {
	    LOGGER.info("handling RemoveConversionEventsFromTrackingPixelEvent " );
	
	    TrackingPixel parentEntity = repository.findById(parentId).get();
	    ConversionEvent child = registry.project( ConversionEvent.class, removeFrom.getConversionEventId());
	    
	    parentEntity.getConversionEvents().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



